import{_ as e,o as s,c as i,a4 as t}from"./chunks/framework.BRzJ4ijD.js";const u=JSON.parse('{"title":"Google BigTable / Spanner / Chubby","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/case/google-trio.md","filePath":"system-design/case/google-trio.md","lastUpdated":1788475713000}'),l={name:"system-design/case/google-trio.md"};function n(r,a,o,h,d,p){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="google-bigtable-spanner-chubby" tabindex="-1">Google BigTable / Spanner / Chubby <a class="header-anchor" href="#google-bigtable-spanner-chubby" aria-label="Permalink to &quot;Google BigTable / Spanner / Chubby&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>Google 三驾马车论文 (2003-2012) 奠定了 modern cloud infrastructure 的基础:</p><ol><li><strong>GFS (2003) / Colossus</strong>: 分布式文件系统, append-only large files, chunk server + master</li><li><strong>BigTable (2006)</strong>: sparse, distributed, persistent multi-dimensional sorted map (like wide-column store before Cassandra); Google&#39;s structured data platform</li><li><strong>Chubby (2006)</strong>: distributed lock service (Paxos-based), 提供 small files + locks, 创始人后来演化 Spanner</li><li><strong>Spanner (2012)</strong>: Google&#39;s globally-distributed SQL database 实现 external consistency (TrueTime+2PL).</li></ol><p>这些 paper 跨 10 年发展, 从 GFS 到 Spanner 逐步打磨。本章概述每系统架构, trade-off, 工程师教训。</p><hr><h2 id="二、gfs-colossus-存储层" tabindex="-1">二、GFS / Colossus (存储层) <a class="header-anchor" href="#二、gfs-colossus-存储层" aria-label="Permalink to &quot;二、GFS / Colossus (存储层)&quot;">​</a></h2><h3 id="架构" tabindex="-1">架构 <a class="header-anchor" href="#架构" aria-label="Permalink to &quot;架构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client → GFS Master (in-memory metadata) </span></span>
<span class="line"><span>   → multiple Chunk Servers (Linux x86 with local disk)</span></span></code></pre></div><ul><li>Files 分成 64 MB chunks, replication 3 (default).</li><li>Master: single for metadata (name space, chunk mapping) — with persistent log + checkpoint recovery.</li><li>Chunk Server: only store data, heartbeats to master.</li></ul><h3 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to &quot;Design&quot;">​</a></h3><ul><li><strong>Optimized for large streaming reads + append writes</strong>. Not random writes. No byte-range locking.</li><li><strong>Append-only log</strong> to files: multiple clients concurrently append; GFS guarantees at-least-once append with record boundary, Application must handle duplicates.</li><li><strong>Single master</strong> for metadata; Chubby later Paxos replace master.</li></ul><h3 id="关键教训" tabindex="-1">关键教训 <a class="header-anchor" href="#关键教训" aria-label="Permalink to &quot;关键教训&quot;">​</a></h3><ul><li>Single master bottleneck: bandwidth master ~1M ops/sec manageable, but failover long.</li><li>Record append: can have duplicate bytes; application padding or checksum.</li></ul><h3 id="后继-colossus-d" tabindex="-1">后继: Colossus / D <a class="header-anchor" href="#后继-colossus-d" aria-label="Permalink to &quot;后继: Colossus / D&quot;">​</a></h3><p>GFS 演进到 Colossus (distributed, no single metadata server, real-time replication, high usage in Google storage stack). Spanner 及 BigTable sit on Colossus.</p><hr><h2 id="三、bigtable-2006-—-wide-column-store" tabindex="-1">三、BigTable (2006) — Wide-column Store <a class="header-anchor" href="#三、bigtable-2006-—-wide-column-store" aria-label="Permalink to &quot;三、BigTable (2006) — Wide-column Store&quot;">​</a></h2><h3 id="数据模型" tabindex="-1">数据模型 <a class="header-anchor" href="#数据模型" aria-label="Permalink to &quot;数据模型&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(row, column_family:column, timestamp) → cell value</span></span>
<span class="line"><span>Sorted by row lexicographically.</span></span></code></pre></div><p>Sparse: each row can have different columns, for web crawl data.</p><h3 id="架构-1" tabindex="-1">架构 <a class="header-anchor" href="#架构-1" aria-label="Permalink to &quot;架构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client → BigTable Master (lightweight)</span></span>
<span class="line"><span>Tablet servers (serve data + Paxos-based replication)</span></span>
<span class="line"><span>Backed by GFS for storing SSTables + WAL.</span></span>
<span class="line"><span>Chubby lock service for master election.</span></span></code></pre></div><ul><li>Tablets: contiguous row-range (dynamic split). ~100MB each.</li><li>SSTables: immutable, LSM-tree compaction (compaction merges + delete tombstone).</li><li>WAL on GFS + MemTable scan.</li></ul><h3 id="design-decisions" tabindex="-1">Design decisions <a class="header-anchor" href="#design-decisions" aria-label="Permalink to &quot;Design decisions&quot;">​</a></h3><ul><li>Locality group per column family: can group frequently accessed columns together in memory (e.g., <code>content</code> family vs <code>metadata</code> family).</li><li>Bloom filter per SSTable, reduce random reads.</li><li>Single-row transaction (atomic read-modify-write) within a row.</li></ul><h3 id="关键教训-1" tabindex="-1">关键教训 <a class="header-anchor" href="#关键教训-1" aria-label="Permalink to &quot;关键教训&quot;">​</a></h3><ul><li>tablet split/rebalance 用 Chubby lock 调整; 运行中建复 杂 拆分 成本 高。</li><li>tablet server crash 需 WAL replay (from GFS) 重启, recovery time minutes.</li></ul><hr><h2 id="四、chubby-2006-—-lock-service" tabindex="-1">四、Chubby (2006) — lock service <a class="header-anchor" href="#四、chubby-2006-—-lock-service" aria-label="Permalink to &quot;四、Chubby (2006) — lock service&quot;">​</a></h2><h3 id="目的" tabindex="-1">目的 <a class="header-anchor" href="#目的" aria-label="Permalink to &quot;目的&quot;">​</a></h3><p>Paxos-based library for distributed coordination (like a small Zookeeper) for master election + locking.</p><h3 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Open(file), Close(file), GetContents(), SetContents()</span></span>
<span class="line"><span>Lock(file), TryLock(file), GetSequencer()</span></span></code></pre></div><ul><li>文件 小 (&lt; 256KB) — not file system, but lock + config store.</li><li>Session lease: client lease 60s, renew each 30s heartbeat.</li><li>Client 拿到 sequencer 后 lock 保证 顺序.</li></ul><h3 id="复制" tabindex="-1">复制 <a class="header-anchor" href="#复制" aria-label="Permalink to &quot;复制&quot;">​</a></h3><p>5 instances Paxos group, majority quorum; leader 选 持 有 60s lease.</p><h3 id="关键教训-2" tabindex="-1">关键教训 <a class="header-anchor" href="#关键教训-2" aria-label="Permalink to &quot;关键教训&quot;">​</a></h3><ul><li>Chubby 不可用于 高吞吐 性 —— lock contention 单 leader; 只 hold metadata.</li><li>之后 引入 基于 于 Chubby 的 Spanner Paxos groups replication.</li></ul><hr><h2 id="五、spanner-2012-—-google-s-globally-distributed-sql" tabindex="-1">五、Spanner (2012) — Google&#39;s globally-distributed SQL <a class="header-anchor" href="#五、spanner-2012-—-google-s-globally-distributed-sql" aria-label="Permalink to &quot;五、Spanner (2012) — Google&#39;s globally-distributed SQL&quot;">​</a></h2><h3 id="关键特性" tabindex="-1">关键特性 <a class="header-anchor" href="#关键特性" aria-label="Permalink to &quot;关键特性&quot;">​</a></h3><ol><li><strong>External Consistency</strong>: strict serializable + linearizable across the world (TrueTime + commit-wait).</li><li><strong>SQL</strong> (not just KV), rich query + interleaved tables.</li><li><strong>Sharded into Paxos groups</strong> (one group per data tablet ~100-1000 rows).</li><li><strong>2PC across Paxos groups</strong> for cross-shard transactions.</li><li><strong>TrueTime</strong>: {earliest, latest} API + commit-wait to ensure commit_ts is strictly in the past.</li></ol><h3 id="data-model" tabindex="-1">Data Model <a class="header-anchor" href="#data-model" aria-label="Permalink to &quot;Data Model&quot;">​</a></h3><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Users</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  uid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> INT64 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  email STRING(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">128</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PRIMARY KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Albums</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  uid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> INT64 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  aid INT64 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> STRING(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">128</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PRIMARY KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, aid),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  INTERLEAVE </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">IN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PARENT Users;</span></span></code></pre></div><p>Interleaved tables: Albums stored in same Paxos group as parent Users — join free local reads.</p><h3 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Zone1 Master (with Paxos group)   Zone2   Zone3</span></span>
<span class="line"><span>    |                                |       |</span></span>
<span class="line"><span>   Colossus DFS &lt;-- Paxos log</span></span></code></pre></div><p>每 tablet Paxos group: 5 replicas per zone. Spanner driver knows about sharding and TrueTime.</p><h3 id="关键教训-3" tabindex="-1">关键教训 <a class="header-anchor" href="#关键教训-3" aria-label="Permalink to &quot;关键教训&quot;">​</a></h3><ul><li>commit-wait ~14ms (TrueTime uncertainty). Not cheap; but consistent across continents.</li><li>Interleaved tables is mandatory for performance; without it 2PC cost 高。</li><li>Automatic resharding: tablet split based on size + load.</li></ul><h3 id="spanner-vs-cockroachdb" tabindex="-1">Spanner vs CockroachDB <a class="header-anchor" href="#spanner-vs-cockroachdb" aria-label="Permalink to &quot;Spanner vs CockroachDB&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对比</th><th>Spanner</th><th>CockroachDB</th></tr></thead><tbody><tr><td>Time source</td><td>TrueTime (atomic clock+ GPS)</td><td>HLC (NTP, max offset 250ms)</td></tr><tr><td>External Consistency</td><td>✅ Strictly</td><td>❌ Not supported (bounded staleness)</td></tr><tr><td>SQL dialect</td><td>GoogleSQL</td><td>PostgreSQL</td></tr><tr><td>Interleaved tables</td><td>✅</td><td>❌ (无)</td></tr><tr><td>Deploy model</td><td>Google Cloud only</td><td>open source, any cloud</td></tr><tr><td>License</td><td>Proprietary</td><td>Open Source (BSL now CDL)</td></tr></tbody></table><hr><h2 id="六、综合-impact-three-papers" tabindex="-1">六、综合 Impact: Three Papers <a class="header-anchor" href="#六、综合-impact-three-papers" aria-label="Permalink to &quot;六、综合 Impact: Three Papers&quot;">​</a></h2><p>这三 papers 变成 分布式系统 课程 必读, 同时 produce real products:</p><ol><li><strong>BigTable → HBase</strong> (Apache HBase is open source BigTable rewrite)</li><li><strong>GFS → HDFS</strong> (Apache Hadoop HDFS inspired by GFS)</li><li><strong>Chubby → ZooKeeper / etcd</strong></li><li><strong>Spanner → CockroachDB / YugaByte / TiDB</strong> (followers)</li></ol><p>Google 内部 2003-2012 这 10 年间 实现了 分布式 infrastructure 几乎全部 基板。</p><hr><h2 id="七、典型事故与教训" tabindex="-1">七、典型事故与教训 <a class="header-anchor" href="#七、典型事故与教训" aria-label="Permalink to &quot;七、典型事故与教训&quot;">​</a></h2><h3 id="gfs-chunk-server-fail-domino" tabindex="-1">GFS Chunk server fail domino <a class="header-anchor" href="#gfs-chunk-server-fail-domino" aria-label="Permalink to &quot;GFS Chunk server fail domino&quot;">​</a></h3><p>GFS 早期 整 组 3 chunk server all 同 rack, when rack switch fail, data lost. Fix: cross-rack placement mandatory; ensure all replicas on different rack domains.</p><h3 id="bigtable-tablet-split-storm" tabindex="-1">BigTable Tablet Split Storm <a class="header-anchor" href="#bigtable-tablet-split-storm" aria-label="Permalink to &quot;BigTable Tablet Split Storm&quot;">​</a></h3><p>Too rapid tablet dynamic split: 600 tablets 在一 table→ 2K+ after hours storm: routing overhead cluster slow. Fix: throttle tablet split rate -&gt; background tasks.</p><h3 id="chubby-paxos-leader-election-delay" tabindex="-1">Chubby Paxos Leader Election Delay <a class="header-anchor" href="#chubby-paxos-leader-election-delay" aria-label="Permalink to &quot;Chubby Paxos Leader Election Delay&quot;">​</a></h3><p>Chubby master 崩溃 后 leader election 15s pause 因 lock quorum, clients with stale lease 认 still valid lock, double locking 可能. Fix: higher epoch lease numbers + client always check lease validity.</p><h3 id="spanner-15ms-commit-wait-latency-p99-spike" tabindex="-1">Spanner 15ms commit-wait latency P99 spike <a class="header-anchor" href="#spanner-15ms-commit-wait-latency-p99-spike" aria-label="Permalink to &quot;Spanner 15ms commit-wait latency P99 spike&quot;">​</a></h3><p>跨 zones 1% packet loss causes TrueTime outlier latency up 50ms commit-wait. Fix: network BBR TCP adds congestion control + retry.</p><hr><h2 id="八、易错清单" tabindex="-1">八、易错清单 <a class="header-anchor" href="#八、易错清单" aria-label="Permalink to &quot;八、易错清单&quot;">​</a></h2><ol><li><strong>GFS 不一致 append 乱字节</strong>: record writer 写 需 checksum; ensure application know at-least-once.</li><li><strong>BigTable 单行事务 only</strong>: cross-row multi-table 无 ACID; 必须 自己 embed 应用层 序 + cleanup.</li><li><strong>Spanner commit-wait 依赖 GPS/GPS loss</strong>: 长时间 无 TrueTime = Spanner 暂停写 或 退 成 eventual。 多 GPS + 原子钟 mandatory.</li><li><strong>Interleaved tables 让数据局部 性 write</strong>: 若 child table 高 write, parent group write hot。</li></ol><hr><h2 id="九、这一章带走的东西" tabindex="-1">九、这一章带走的东西 <a class="header-anchor" href="#九、这一章带走的东西" aria-label="Permalink to &quot;九、这一章带走的东西&quot;">​</a></h2><ol><li>GFS/Colossus: 分布式文件系统 append-only optimized for large streaming.</li><li>BigTable: sparse wide-column store with LSM on GFS + Chubby coordination.</li><li>Chubby: Paxos-based lock service bring coordination + 服务 discovery.</li><li>Spanner: globally distributed SQL database — first external consistency implementation, TrueTime 是关键。</li><li>Google 三 papers 贯穿 分布式 infrastructure backbone; virtually every other distributed DB inspired by them.</li><li>&quot;Why can&#39;t Spanner be everywhere cost is ~15ms commit wait, requires Google-level infrastructure&quot;.</li></ol><hr><p>下一节 → <a href="./dynamo-family">Dynamo Family</a></p>`,76)])])}const b=e(l,[["render",n]]);export{u as __pageData,b as default};
